// pressPdf — the file you hand a printer.
//
// Takes rendered pages (RGBA rasters at press resolution) and the job spec and writes a PDF with:
//   • the trim, bleed and media boxes set, so any RIP or POD service knows where to cut;
//   • bleed generated by extending edge pixels when the page wasn't drawn into the bleed;
//   • for CMYK conditions: DeviceCMYK images separated with the condition's GCR and ink limit (TAC),
//     pure black (text) printed in black ink only, transparency flattened onto paper white,
//     crop/registration marks and a colour bar in registration colour, an OutputIntent naming the
//     characterised condition, and the PDF/X-1a:2003 identification keys;
//   • for home and RGB wide-format jobs: a plain RGB PDF (printer drivers and RIPs separate RGB);
//   • optional dielines (cut / crease) stroked in a Separation spot colour with overprint;
//   • optional home-booklet imposition (2-up printer spreads, duplex flip on short edge).
//
// Honest scope: pages are raster (text included) at the chosen resolution — sharp at 300 ppi, but not
// vector type. Separation uses Tela's ICC-less printer model, not the condition's ICC profile, so the
// file follows the PDF/X-1a structure without being certified: run it through your printer's preflight
// (or Acrobat/PitStop) before a long run. The OutputIntent references the registered condition by
// name, which PDF/X-1a permits for registered characterisations; no profile is embedded.

import {
  LineCapStyle, LineJoinStyle, PDFArray, PDFDict, PDFDocument, PDFFont, PDFHexString, PDFName, PDFNumber,
  PDFOperator, PDFPage, PDFPageLeaf, PDFRawStream, PDFString, appendBezierCurve, decodePDFRawStream, beginText, closePath,
  concatTransformationMatrix, drawObject, endText, fill, lineTo, moveTo, popGraphicsState, pushGraphicsState,
  rectangle, setCharacterSpacing, setDashPattern, setFillingCmykColor, setFillingRgbColor, setFontAndSize,
  setGraphicsState, setLineCap, setLineJoin, setLineWidth, setStrokingCmykColor, setStrokingRgbColor,
  setTextMatrix, showText, stroke,
} from 'pdf-lib';
import { separateCmyk, srgbToCmyk } from '../tela/raster/color';
import type { ResolvedFont, VectorPage } from './vector';
import { conditionById } from './conditions';
import { printerMarks } from './marks';
import { saddleStitchSpreads } from './imposition';
import type { DocPrintSpec, SpotColor } from './types';
import { PT_PER_IN } from './types';

export interface RasterPage {
  label: string;
  width: number;
  height: number;
  /** RGBA, row-major, top-left origin. */
  data: Uint8ClampedArray;
  /** True when the raster already contains the bleed area around the trim. */
  includesBleed: boolean;
  /** Text and shapes drawn as real vector on top of the raster (which then holds only images/effects). */
  vector?: VectorPage;
}

export interface Dieline {
  pageIndex: number;
  /** Absolute M/L/C/Z paths in inches, origin = top-left of the trim. */
  paths: string[];
  spot: SpotColor;
}

export interface PressPdfOptions {
  title: string;
  author?: string;
  spec: DocPrintSpec;
  /** Raster resolution the pages were rendered at, pixels per inch. */
  dpi: number;
  pages: RasterPage[];
  dielines?: Dieline[];
  /** 'home-booklet' imposes pages as folded printer spreads for duplex home printing. */
  impose?: 'none' | 'home-booklet';
  /** Draw printer's marks (ignored for home jobs). Defaults to spec.marks. */
  marks?: boolean;
  /** Fonts for vector text, by fontKey (vector.ts). Embedded and subset; required for any VectorText. */
  fonts?: Record<string, ResolvedFont>;
  now?: Date;
}

export interface PressPdfResult {
  bytes: Uint8Array;
  colorModel: 'CMYK' | 'RGB';
  conformance: string;
  pageCount: number;
  /** Highest total ink (percent) found on each output page, after limiting. */
  maxTac: number[];
  notes: string[];
}

// ── Raster helpers (exported for tests) ──────────────────────────────────────

/** Grow a raster by `b` px on every side, repeating the edge pixels. */
export function extendEdges(src: { width: number; height: number; data: Uint8ClampedArray }, b: number): { width: number; height: number; data: Uint8ClampedArray } {
  if (b <= 0) return src;
  const W = src.width + 2 * b, H = src.height + 2 * b, out = new Uint8ClampedArray(W * H * 4);
  for (let y = 0; y < H; y++) {
    const sy = Math.min(src.height - 1, Math.max(0, y - b));
    for (let x = 0; x < W; x++) {
      const sx = Math.min(src.width - 1, Math.max(0, x - b)), si = (sy * src.width + sx) * 4, di = (y * W + x) * 4;
      out[di] = src.data[si]; out[di + 1] = src.data[si + 1]; out[di + 2] = src.data[si + 2]; out[di + 3] = src.data[si + 3];
    }
  }
  return { width: W, height: H, data: out };
}

/** Composite onto paper white and drop alpha (PDF/X-1a forbids transparency). */
export function flattenOnWhite(data: Uint8ClampedArray): Uint8ClampedArray {
  const out = new Uint8ClampedArray(data.length);
  for (let i = 0; i < data.length; i += 4) {
    const a = data[i + 3] / 255;
    out[i] = Math.round(data[i] * a + 255 * (1 - a)); out[i + 1] = Math.round(data[i + 1] * a + 255 * (1 - a)); out[i + 2] = Math.round(data[i + 2] * a + 255 * (1 - a)); out[i + 3] = 255;
  }
  return out;
}

/** Separate a flattened RGBA raster to interleaved CMYK bytes, K-only for pure black, and measure TAC. */
export function toPressCmyk(bm: { width: number; height: number; data: Uint8ClampedArray }, tacPct: number, gcr: number): { cmyk: Uint8Array; maxTac: number } {
  const { cmyk } = separateCmyk(bm, { gcr, inkLimit: tacPct / 100 });
  let maxTac = 0;
  for (let p = 0, i = 0; i < cmyk.length; p++, i += 4) {
    const r = bm.data[p * 4], g = bm.data[p * 4 + 1], b = bm.data[p * 4 + 2];
    if (r <= 10 && g <= 10 && b <= 10) { cmyk[i] = 0; cmyk[i + 1] = 0; cmyk[i + 2] = 0; cmyk[i + 3] = 255; }
    const t = cmyk[i] + cmyk[i + 1] + cmyk[i + 2] + cmyk[i + 3];
    if (t > maxTac) maxTac = t;
  }
  return { cmyk, maxTac: (maxTac / 255) * 100 };
}

function toRgb(data: Uint8ClampedArray): Uint8Array {
  const out = new Uint8Array((data.length / 4) * 3);
  for (let i = 0, j = 0; i < data.length; i += 4, j += 3) { out[j] = data[i]; out[j + 1] = data[i + 1]; out[j + 2] = data[i + 2]; }
  return out;
}

export { parsePath, translatePath } from './paths';
import { parsePath } from './paths';

// ── Writer ──────────────────────────────────────────────────────────────────

export async function buildPressPdf(o: PressPdfOptions): Promise<PressPdfResult> {
  const cond = conditionById(o.spec.conditionId);
  const cmyk = cond.colorModel === 'CMYK';
  const home = cond.intent === 'home';
  const notes: string[] = [];
  const bleedIn = home ? 0 : o.spec.bleedIn;
  // Imposed home booklets are trimmed by the fold, not a guillotine: no marks.
  const drawMarks = !home && o.impose !== 'home-booklet' && (o.marks ?? (o.spec.marks.crop || o.spec.marks.registration || o.spec.marks.colorBar));
  const [trimW, trimH] = o.spec.trimIn;
  const now = o.now ?? new Date();

  const pdf = await PDFDocument.create();
  pdf.setTitle(o.title || 'Untitled');
  if (o.author) pdf.setAuthor(o.author);
  pdf.setCreator('Plajah Tela');
  pdf.setProducer('Plajah Tela print engine');
  pdf.setCreationDate(now);
  pdf.setModificationDate(now);

  // Build each logical page's image XObject once (imposition may place it on another sheet).
  const bleedPx = Math.round(bleedIn * o.dpi);
  const maxTac: number[] = [];
  const images = o.pages.map((pg, idx) => {
    const withBleed = pg.includesBleed || bleedPx === 0 ? pg : extendEdges(pg, bleedPx);
    if (!pg.includesBleed && bleedPx > 0) notes.push(`${pg.label}: bleed generated by extending edges.`);
    const flat = { width: withBleed.width, height: withBleed.height, data: flattenOnWhite(withBleed.data) };
    let stream;
    if (cmyk) {
      const { cmyk: bytes, maxTac: t } = toPressCmyk(flat, cond.tac, cond.gcr);
      maxTac[idx] = Math.round(t);
      stream = pdf.context.flateStream(bytes, { Type: 'XObject', Subtype: 'Image', Width: flat.width, Height: flat.height, ColorSpace: 'DeviceCMYK', BitsPerComponent: 8 });
    } else {
      maxTac[idx] = 0;
      stream = pdf.context.flateStream(toRgb(flat.data), { Type: 'XObject', Subtype: 'Image', Width: flat.width, Height: flat.height, ColorSpace: 'DeviceRGB', BitsPerComponent: 8 });
    }
    return pdf.context.register(stream);
  });

  // Separation colour spaces for dielines (tint transform: linear blend to the process fallback).
  const spotRefs = new Map<string, ReturnType<typeof pdf.context.register>>();
  for (const d of o.dielines || []) {
    if (spotRefs.has(d.spot.name)) continue;
    const fn = pdf.context.obj({ FunctionType: 2, Domain: [0, 1], C0: [0, 0, 0, 0], C1: d.spot.cmykFallback.map(v => v / 100), N: 1 });
    const cs = pdf.context.obj([PDFName.of('Separation'), PDFName.of(d.spot.name.replace(/\s+/g, '#20')), PDFName.of('DeviceCMYK'), pdf.context.register(fn)]);
    spotRefs.set(d.spot.name, pdf.context.register(cs));
  }

  // ── Vector layer: embedded fonts, ink, shapes, words ──
  const usedFonts = new Set(o.pages.flatMap(pg => pg.vector?.texts.map(t => t.fontKey) || []));
  const embedded = new Map<string, PDFFont>();
  if (usedFonts.size) {
    const { default: fontkit } = await import('@pdf-lib/fontkit');
    pdf.registerFontkit(fontkit);
    for (const key of usedFonts) {
      const f = o.fonts?.[key];
      if (!f) throw new Error(`No font bytes for ${key}; leave that text in the raster or supply the font.`);
      const strings = o.pages.flatMap(pg => pg.vector?.texts.filter(t => t.fontKey === key).map(t => t.text) || []);
      const subset = await subsetKeepsGlyphs(f.bytes, strings, fontkit);
      if (!subset) notes.push(`${f.family}${f.weight !== 400 ? ` ${f.weight}` : ''} embedded in full: subsetting this font would drop glyph outlines.`);
      embedded.set(key, await pdf.embedFont(f.bytes, { subset }));
    }
  }
  const ink = (rgb: [number, number, number]) => {
    if (!cmyk) return { fill: setFillingRgbColor(rgb[0] / 255, rgb[1] / 255, rgb[2] / 255), stroke: setStrokingRgbColor(rgb[0] / 255, rgb[1] / 255, rgb[2] / 255) };
    // Pure black prints in black ink only, like the raster path; everything else is separated with the
    // condition's GCR and ink limit.
    const [c, m, y, k] = rgb[0] <= 10 && rgb[1] <= 10 && rgb[2] <= 10 ? [0, 0, 0, 1] : srgbToCmyk(rgb[0] / 255, rgb[1] / 255, rgb[2] / 255, { gcr: cond.gcr, inkLimit: cond.tac / 100 });
    return { fill: setFillingCmykColor(c, m, y, k), stroke: setStrokingCmykColor(c, m, y, k) };
  };
  let vecWords = 0, vecShapes = 0, scaledOff = 0;
  const fontNames = new Map<string, PDFName>();
  const drawVector = (page: PDFPage, vec: VectorPage, ox: number, oy: number, toPdfY: (y: number) => number) => {
    const P = (x: number, y: number) => [(ox + x) * PT_PER_IN, toPdfY(oy + y)] as const;
    // Clip the vector layer to this page's bleed box so nothing reaches the marks or the next page.
    page.pushOperators(pushGraphicsState(), rectangle((ox - bleedIn) * PT_PER_IN, toPdfY(oy + trimH + bleedIn), (trimW + 2 * bleedIn) * PT_PER_IN, (trimH + 2 * bleedIn) * PT_PER_IN), PDFOperator.of('W' as any), PDFOperator.of('n' as any));
    for (const s of vec.shapes) {
      if (!s.fill && !s.stroke) continue;
      page.pushOperators(pushGraphicsState());
      if (s.fill) page.pushOperators(ink(s.fill).fill);
      if (s.stroke) {
        page.pushOperators(ink(s.stroke).stroke, setLineWidth(s.strokePt ?? 1));
        if (s.cap) page.pushOperators(setLineCap(s.cap === 'round' ? LineCapStyle.Round : s.cap === 'square' ? LineCapStyle.Projecting : LineCapStyle.Butt));
        if (s.join) page.pushOperators(setLineJoin(s.join === 'round' ? LineJoinStyle.Round : s.join === 'bevel' ? LineJoinStyle.Bevel : LineJoinStyle.Miter));
        if (s.dashPt?.length) page.pushOperators(setDashPattern(s.dashPt, 0));
      }
      for (const c of parsePath(s.d)) {
        if (c.op === 'M') page.pushOperators(moveTo(...P(c.pts[0], c.pts[1])));
        else if (c.op === 'L') page.pushOperators(lineTo(...P(c.pts[0], c.pts[1])));
        else if (c.op === 'C') page.pushOperators(appendBezierCurve(...P(c.pts[0], c.pts[1]), ...P(c.pts[2], c.pts[3]), ...P(c.pts[4], c.pts[5])));
        else page.pushOperators(closePath());
      }
      const paint = s.fill && s.stroke ? (s.evenOdd ? 'B*' : 'B') : s.fill ? (s.evenOdd ? 'f*' : 'f') : 'S';
      page.pushOperators(PDFOperator.of(paint as any), popGraphicsState());
      vecShapes++;
    }
    for (const t of vec.texts) {
      const font = embedded.get(t.fontKey); if (!font) continue;
      const nameKey = `${t.fontKey}@${page.ref.toString()}`;
      let name = fontNames.get(nameKey);
      if (!name) { name = page.node.newFontDictionary('F', font.ref); fontNames.set(nameKey, name); }
      // Match the browser's word width: PDF glyph advance + letter spacing, scaled with Tz. A big
      // mismatch means a different face was measured (e.g. a fallback): draw unscaled and count it.
      const natural = font.widthOfTextAtSize(t.text, t.sizePt) + t.letterSpacingPt * [...t.text].length;
      let tz = natural > 0 ? (t.widthIn * PT_PER_IN) / natural : 1;
      if (tz < 0.85 || tz > 1.15) { tz = 1; scaledOff++; }
      const [x, y] = P(t.xIn, t.baselineIn);
      page.pushOperators(
        pushGraphicsState(), ink(t.color).fill, beginText(), setFontAndSize(name, t.sizePt),
        setCharacterSpacing(t.letterSpacingPt), PDFOperator.of('Tz' as any, [PDFNumber.of(Math.round(tz * 10000) / 100)]),
        setTextMatrix(1, 0, 0, 1, x, y), showText(font.encodeText(t.text)), endText(), popGraphicsState(),
      );
      vecWords++;
    }
    page.pushOperators(popGraphicsState());
  };

  const slots: Array<Array<number | null>> = o.impose === 'home-booklet'
    ? saddleStitchSpreads(o.pages.length).flatMap(s => [s.front, s.back]).map(side => side.map(n => (n === null ? null : n - 1)))
    : o.pages.map((_, i) => [i]);
  if (o.impose === 'home-booklet') notes.push('Imposed as a booklet: print double-sided, flip on the short edge, fold and staple.');

  const marksGeo = drawMarks ? printerMarks({ trimIn: [trimW, trimH], bleedIn, marks: o.spec.marks }) : null;
  const pagePerSheet = slots[0]?.length || 1;
  const sheetW = marksGeo ? marksGeo.mediaIn[0] : (trimW + 2 * bleedIn) * pagePerSheet;
  const sheetH = marksGeo ? marksGeo.mediaIn[1] : trimH + 2 * bleedIn;

  for (const slot of slots) {
    const page = pdf.addPage([sheetW * PT_PER_IN, sheetH * PT_PER_IN]);
    const toPdfY = (yIn: number) => (sheetH - yIn) * PT_PER_IN;
    // Where the bleed box of slot k starts, in media inches (top-left origin).
    const originX = marksGeo ? marksGeo.bleedBox.x : 0, originY = marksGeo ? marksGeo.bleedBox.y : 0;
    const cellW = trimW + 2 * bleedIn;

    if (!marksGeo || pagePerSheet === 1) {
      const trimBox = { x: originX + bleedIn, y: originY + bleedIn, w: trimW * pagePerSheet, h: trimH };
      setBox(page.node, 'TrimBox', trimBox, toPdfY);
      setBox(page.node, 'BleedBox', { x: originX, y: originY, w: cellW * pagePerSheet - (pagePerSheet - 1) * 2 * bleedIn, h: trimH + 2 * bleedIn }, toPdfY);
    }
    slot.forEach((pageIdx, k) => {
      if (pageIdx === null || !images[pageIdx]) return;
      const name = page.node.newXObject('Pg', images[pageIdx]);
      const x = originX + k * trimW, y = originY;
      page.pushOperators(
        pushGraphicsState(),
        concatTransformationMatrix(cellW * PT_PER_IN, 0, 0, (trimH + 2 * bleedIn) * PT_PER_IN, x * PT_PER_IN, toPdfY(y + trimH + 2 * bleedIn)),
        drawObject(name),
        popGraphicsState(),
      );
      const vec = o.pages[pageIdx].vector;
      if (vec) drawVector(page, vec, x + bleedIn, y + bleedIn, toPdfY);
    });

    // Dielines: Separation stroke with overprint so the cut line never knocks out the art.
    const sheetDielines = (o.dielines || []).filter(d => slot.includes(d.pageIndex));
    if (sheetDielines.length) {
      const gs = page.node.newExtGState('OP', pdf.context.obj({ Type: 'ExtGState', OP: true, op: true, OPM: 1 }));
      const res = page.node.Resources()!;
      const csDict = pdf.context.obj({});
      res.set(PDFName.of('ColorSpace'), csDict);
      sheetDielines.forEach((d, n) => {
        const csName = `CS${n}`;
        csDict.set(PDFName.of(csName), spotRefs.get(d.spot.name)!);
        const k = slot.indexOf(d.pageIndex);
        const ox = originX + bleedIn + k * trimW, oy = originY + bleedIn;
        page.pushOperators(pushGraphicsState(), setGraphicsState(gs), PDFOperator.of('CS' as any, [PDFName.of(csName)]), PDFOperator.of('SCN' as any, [PDFNumber.of(1)]), setLineWidth(0.5));
        for (const path of d.paths) {
          for (const c of parsePath(path)) {
            const P = (i: number) => [(ox + c.pts[i]) * PT_PER_IN, toPdfY(oy + c.pts[i + 1])] as const;
            if (c.op === 'M') page.pushOperators(moveTo(...P(0)));
            else if (c.op === 'L') page.pushOperators(lineTo(...P(0)));
            else if (c.op === 'C') page.pushOperators(appendBezierCurve(...P(0), ...P(2), ...P(4)));
            else page.pushOperators(closePath());
          }
          page.pushOperators(stroke());
        }
        page.pushOperators(popGraphicsState());
      });
      notes.push(`Dielines drawn in spot ${[...new Set(sheetDielines.map(d => d.spot.name))].join(', ')} (overprint).`);
    }

    if (marksGeo) {
      // Registration colour (all inks) so marks appear on every plate.
      const reg: [number, number, number, number] = cmyk ? [1, 1, 1, 1] : [0, 0, 0, 1];
      page.pushOperators(pushGraphicsState(), setStrokingCmykColor(reg[0], reg[1], reg[2], reg[3]), setLineWidth(0.25));
      for (const l of marksGeo.lines) page.pushOperators(moveTo(l.x1 * PT_PER_IN, toPdfY(l.y1)), lineTo(l.x2 * PT_PER_IN, toPdfY(l.y2)), stroke());
      for (const r of marksGeo.registration) {
        page.pushOperators(...circleOps(r.cx * PT_PER_IN, toPdfY(r.cy), r.r * PT_PER_IN), stroke(),
          moveTo((r.cx - r.r * 1.6) * PT_PER_IN, toPdfY(r.cy)), lineTo((r.cx + r.r * 1.6) * PT_PER_IN, toPdfY(r.cy)), stroke(),
          moveTo(r.cx * PT_PER_IN, toPdfY(r.cy - r.r * 1.6)), lineTo(r.cx * PT_PER_IN, toPdfY(r.cy + r.r * 1.6)), stroke());
      }
      if (marksGeo.colorBar && cmyk) {
        const bar = marksGeo.colorBar;
        bar.patches.forEach((p, i) => page.pushOperators(setFillingCmykColor(p.c / 100, p.m / 100, p.y / 100, p.k / 100), rectangle((bar.x + i * bar.patchIn) * PT_PER_IN, toPdfY(bar.y + bar.patchIn), bar.patchIn * PT_PER_IN, bar.patchIn * PT_PER_IN), fill()));
      }
      page.pushOperators(popGraphicsState());
      setBox(page.node, 'TrimBox', marksGeo.trimBox, toPdfY);
      setBox(page.node, 'BleedBox', marksGeo.bleedBox, toPdfY);
    }
  }

  if (vecWords || vecShapes) {
    notes.push(`Vector: ${vecWords} words as live text in ${embedded.size} embedded font${embedded.size === 1 ? '' : 's'}, ${vecShapes} shapes as paths.`);
    for (const f of [...usedFonts].map(k => o.fonts?.[k]).filter((f): f is ResolvedFont => !!f?.substitutedFor)) {
      notes.push(`Font substituted: ${f.substitutedFor} → ${f.family} (no embeddable file for ${f.substitutedFor}).`);
    }
    if (scaledOff) notes.push(`${scaledOff} words measured in a different face than the one embedded; drawn at natural width.`);
    const raster: Record<string, number> = {};
    for (const pg of o.pages) for (const [r, n] of Object.entries(pg.vector?.rasterized || {})) raster[r] = (raster[r] || 0) + n;
    const rs = Object.entries(raster).filter(([, n]) => n > 0);
    if (rs.length) notes.push(`Kept as raster: ${rs.map(([r, n]) => `${n} ${r}`).join(', ')}.`);
  }
  let conformance = 'PDF (RGB)';
  if (cmyk && cond.outputConditionIdentifier) {
    const intent = pdf.context.obj({
      Type: 'OutputIntent', S: 'GTS_PDFX',
      OutputConditionIdentifier: PDFString.of(cond.outputConditionIdentifier),
      OutputCondition: PDFString.of(cond.label),
      RegistryName: PDFString.of(cond.registryName || 'http://www.color.org'),
      Info: PDFString.of(cond.label),
    });
    pdf.catalog.set(PDFName.of('OutputIntents'), pdf.context.obj([pdf.context.register(intent)]) as PDFArray);
    // pdf-lib keeps the Info dict private; it lives at trailer /Info.
    const info = pdf.context.lookup(pdf.context.trailerInfo.Info, PDFDict);
    info.set(PDFName.of('GTS_PDFXVersion'), PDFString.of('PDF/X-1a:2003'));
    info.set(PDFName.of('GTS_PDFXConformance'), PDFString.of('PDF/X-1a:2003'));
    info.set(PDFName.of('Trapped'), PDFName.of('False'));
    conformance = 'PDF/X-1a:2003 structure (not certified — run your printer’s preflight)';
  }
  const id = PDFHexString.of(Array.from(crypto.getRandomValues(new Uint8Array(16)), b => b.toString(16).padStart(2, '0')).join(''));
  pdf.context.trailerInfo.ID = pdf.context.obj([id, id]);

  // Subset fonts must be named TAG+Name (ISO 32000 §9.6.4); pdf-lib writes Name-NNNN. Flush the
  // embedded fonts, then rename the Type0 font, its descendant and the descriptor.
  if (embedded.size) {
    await pdf.flush();
    for (const [key, font] of embedded) {
      const type0 = pdf.context.lookup(font.ref, PDFDict);
      const base = type0.lookup(PDFName.of('BaseFont'), PDFName).decodeText().replace(/^[A-Z]{6}\+/, '');
      let h = 0; for (const ch of key) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
      const tag = Array.from({ length: 6 }, (_, i) => String.fromCharCode(65 + ((h >>> (i * 5)) % 26))).join('');
      const named = PDFName.of(`${tag}+${base}`);
      type0.set(PDFName.of('BaseFont'), named);
      const cid = type0.lookup(PDFName.of('DescendantFonts'), PDFArray).lookup(0, PDFDict);
      cid.set(PDFName.of('BaseFont'), named);
      cid.lookup(PDFName.of('FontDescriptor'), PDFDict).set(PDFName.of('FontName'), named);
    }
  }
  const bytes = await pdf.save({ useObjectStreams: false });
  // pdf-lib's writer always emits %PDF-1.7; PDF/X-1a:2003 requires 1.4. Same length, so no offsets move.
  // Nothing written above uses a post-1.4 feature (no object streams, no transparency, no layers).
  if (conformance.startsWith('PDF/X')) bytes.set(new TextEncoder().encode('%PDF-1.4'), 0);
  return { bytes, colorModel: cmyk ? 'CMYK' : 'RGB', conformance, pageCount: slots.length, maxTac, notes };
}

/**
 * Wide-format panel file: one page per wrap panel at its real printed size (RGB; wide-format RIPs
 * separate for their own inks). Trim = media: shops add their own registration for tiling.
 */
export async function buildPanelPdf(title: string, panels: Array<{ label: string; widthIn: number; heightIn: number; raster: { width: number; height: number; data: Uint8ClampedArray } }>): Promise<Uint8Array> {
  const pdf = await PDFDocument.create();
  pdf.setTitle(title); pdf.setCreator('Plajah Tela'); pdf.setProducer('Plajah Tela print engine');
  pdf.setSubject(panels.map(p => `${p.label} ${p.widthIn.toFixed(2)}×${p.heightIn.toFixed(2)} in`).join('; '));
  for (const p of panels) {
    const img = pdf.context.register(pdf.context.flateStream(toRgb(flattenOnWhite(p.raster.data)), { Type: 'XObject', Subtype: 'Image', Width: p.raster.width, Height: p.raster.height, ColorSpace: 'DeviceRGB', BitsPerComponent: 8 }));
    // PDF pages top out at 14,400 units (200 in); longer panels use UserUnit so they stay full size.
    const unit = Math.max(1, Math.ceil(Math.max(p.widthIn, p.heightIn) * PT_PER_IN / 14400));
    const W = (p.widthIn * PT_PER_IN) / unit, H = (p.heightIn * PT_PER_IN) / unit;
    const page = pdf.addPage([W, H]);
    if (unit > 1) page.node.set(PDFName.of('UserUnit'), PDFNumber.of(unit));
    const name = page.node.newXObject('Pn', img);
    page.pushOperators(pushGraphicsState(), concatTransformationMatrix(W, 0, 0, H, 0, 0), drawObject(name), popGraphicsState());
    page.node.set(PDFName.of('TrimBox'), pdf.context.obj([0, 0, W, H]));
  }
  return pdf.save({ useObjectStreams: false });
}

/**
 * fontkit's TrueType subsetter loses the outlines of some glyphs in some fonts (seen with Inter: o, b,
 * t, i, c, s, e, p, l came out empty). Dry-run the subset in a scratch document and check every glyph
 * the text needs still has an outline; if not, the caller embeds the whole font instead.
 */
export async function subsetKeepsGlyphs(bytes: Uint8Array, strings: string[], fontkit: any): Promise<boolean> {
  try {
    const scratch = await PDFDocument.create();
    scratch.registerFontkit(fontkit);
    const font = await scratch.embedFont(bytes, { subset: true });
    const ids = new Set<number>();
    const visible = strings.map(s => s.replace(/\s+/g, '')).filter(Boolean);
    for (const s of visible) for (const h of font.encodeText(s).asString().replace(/[<>]/g, '').match(/.{4}/g) || []) ids.add(parseInt(h, 16));
    await scratch.flush();
    const type0 = scratch.context.lookup(font.ref, PDFDict);
    const cid = type0.lookup(PDFName.of('DescendantFonts'), PDFArray).lookup(0, PDFDict);
    const file = cid.lookup(PDFName.of('FontDescriptor'), PDFDict).lookup(PDFName.of('FontFile2'));
    if (!(file instanceof PDFRawStream)) return false;
    const program = fontkit.create(decodePDFRawStream(file).decode());
    for (const id of ids) if (!program.getGlyph(id)?.path?.commands?.length) return false;
    return true;
  } catch {
    return false;
  }
}

function setBox(node: PDFPageLeaf, key: 'TrimBox' | 'BleedBox', r: { x: number; y: number; w: number; h: number }, toPdfY: (y: number) => number) {
  const box = [r.x * PT_PER_IN, toPdfY(r.y + r.h), (r.x + r.w) * PT_PER_IN, toPdfY(r.y)].map(v => Math.round(v * 1000) / 1000);
  node.set(PDFName.of(key), node.context.obj(box));
}

function circleOps(cx: number, cy: number, r: number) {
  const k = 0.5523 * r;
  return [
    moveTo(cx + r, cy),
    appendBezierCurve(cx + r, cy + k, cx + k, cy + r, cx, cy + r),
    appendBezierCurve(cx - k, cy + r, cx - r, cy + k, cx - r, cy),
    appendBezierCurve(cx - r, cy - k, cx - k, cy - r, cx, cy - r),
    appendBezierCurve(cx + k, cy - r, cx + r, cy - k, cx + r, cy),
    closePath(),
  ];
}
